ATTACH ':memory:' AS aux; CREATE TABLE main.t1(x, y); CREATE TEMP TABLE t1(x, y); CREATE TABLE aux.t1(x, y); CREATE TABLE main.result(main_count, temp_count, aux_count); INSERT INTO main.result SELECT (SELECT count(*) FROM main.sqlite_master WHERE type='table' AND name='t1'), (SELECT count(*) FROM temp.sqlite_master WHERE type='table' AND name='t1'), (SELECT count(*) FROM aux.sqlite_master WHERE type='table' AND name='t1');